    adcs_status_t status;
    double energy_acc = 0.0;
    size_t i;

    /* Check for NULL pointers */
    if ((wheels == NULL) || (field == NULL) || (command == NULL) || 
        (momentum == NULL) || (torque == NULL) || (energy == NULL) || (dissipation == NULL)) {
        if (momentum) *momentum = (adcs_vec3_t){0, 0, 0};
        if (command) { command->command = (adcs_vec3_t){0, 0, 0}; command->saturated_axes = 0U; }
        if (torque) *torque = (adcs_vec3_t){0, 0, 0};
        if (energy) *energy = 0.0;
        if (dissipation) *dissipation = 0.0;
        return ADCS_E_NULL;
    }

    /* Check count range */
    if (count < 1 || count > 16) {
        *momentum = (adcs_vec3_t){0, 0, 0};
        command->command = (adcs_vec3_t){0, 0, 0};
        command->saturated_axes = 0U;
        *torque = (adcs_vec3_t){0, 0, 0};
        *energy = 0.0;
        *dissipation = 0.0;
        return ADCS_E_RANGE;
    }

    /* Check field finiteness */
    if (!adcs_is_finite_vec3(field)) {
        *momentum = (adcs_vec3_t){0, 0, 0};
        command->command = (adcs_vec3_t){0, 0, 0};
        command->saturated_axes = 0U;
        *torque = (adcs_vec3_t){0, 0, 0};
        *energy = 0.0;
        *dissipation = 0.0;
        return ADCS_E_RANGE;
    }

    /* Compute cluster momentum */
    status = adcs_wheel_momentum(wheels, count, momentum);
    if (status != ADCS_OK) {
        command->command = (adcs_vec3_t){0, 0, 0};
        command->saturated_axes = 0U;
        *torque = (adcs_vec3_t){0, 0, 0};
        *energy = 0.0;
        *dissipation = 0.0;
        return status;
    }

    /* Compute stored wheel energy: sum(0.5 * J_i * omega_i^2) */
    for (i = 0; i < count; ++i) {
        energy_acc += 0.5 * wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s * wheels[i].speed_rad_s;
    }
    *energy = energy_acc;

    /* Request bounded magnetic unloading command and achievable torque */
    status = adcs_momentum_unload_dipole(momentum, field, gain, dipole_limit, command, torque);
    if (status != ADCS_OK) {
        return status;
    }

    /* Compute dissipation: dot(momentum, torque) */
    *dissipation = adcs_vec3_dot(momentum, torque);

    return ADCS_OK;
}

