    if (st != ADCS_OK) {
        // Requirement: adcs_wheel_momentum failure -> ADCS_E_RANGE
        // The function likely returns ADCS_E_RANGE for invalid data.
        // We zero outputs as per "zero outputs on failure" for invalid clusters/data.
        goto zero_outputs_and_return_range;
    }

    // 4. Compute stored wheel energy
    // Since adcs_wheel_momentum succeeded, wheel params are valid (finite, J>0, etc.)
